Fixes: 3557baabf280 ("[L2TP]: PPP over L2TP driver core")
Reported-by: syzbot+ci3edea60a44225dec@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/netdev/69a1dfba.050a0220.3a55be.0026.GAE@google.com/
Signed-off-by: Alice Mikityanska <alice@isovalent.com>
Link: https://patch.msgid.link/20260403174949.843941-1-alice.kernel@fastmail.im
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The l2tp_xmit_core function in the L2TP core does not check if the computed UDP length (udp_len = uhlen + session->hdr_len + data_len) exceeds the maximum value representable by a 16-bit unsigned integer (U16_MAX). When an oversized packet is sent, the subsequent assignment `uh->len = htons(udp_len)` truncates the value to 16 bits, resulting in a malformed UDP packet and potentially triggering a kernel warning (as seen in the syzbot report). This bug exists in the upstream code and was exposed by a debug WARN in a related patch series.

Here is the patch:

 static int l2tp_xmit_core(struct l2tp_session *session, struct sk_buff *skb, unsigned int *len)
 {
 	struct l2tp_tunnel *tunnel = session->tunnel;
 	unsigned int data_len = skb->len;
 	struct sock *sk = tunnel->sock;
 	int headroom, uhlen, udp_len;
 	int ret = NET_XMIT_SUCCESS;
 	struct inet_sock *inet;
 	struct udphdr *uh;

 	/* Check that there's enough headroom in the skb to insert IP,
 	 * UDP and L2TP headers. If not enough, expand it to
 	 * make room. Adjust truesize.
 	 */
 	uhlen = (tunnel->encap == L2TP_ENCAPTYPE_UDP) ? sizeof(*uh) : 0;
 	headroom = NET_SKB_PAD + sizeof(struct iphdr) + uhlen + session->hdr_len;
 	if (skb_cow_head(skb, headroom)) {
 		kfree_skb(skb);
 		return NET_XMIT_DROP;
 	}

 	/* Setup L2TP header */
 	if (tunnel->version == L2TP_HDR_VER_2)
 		l2tp_build_l2tpv2_header(session, __skb_push(skb, session->hdr_len));
 	else
 		l2tp_build_l2tpv3_header(session, __skb_push(skb, session->hdr_len));

 	/* Reset control buffer */
 	memset(skb->cb, 0, sizeof(skb->cb));

 	nf_reset_ct(skb);

 	/* L2TP uses its own lockdep subclass to avoid lockdep splats caused by
 	 * nested socket calls on the same lockdep socket class. This can
 	 * happen when data from a user socket is routed over l2tp, which uses
 	 * another userspace socket.
 	 */
 	spin_lock_nested(&sk->sk_lock.slock, L2TP_DEPTH_NESTING);

 	if (sock_owned_by_user(sk)) {
 		kfree_skb(skb);
 		ret = NET_XMIT_DROP;
 		goto out_unlock;
 	}

 	/* The user-space may change the connection status for the user-space
 	 * provided socket at run time: we must check it under the socket lock
 	 */
 	if (tunnel->fd >= 0 && sk->sk_state != TCP_ESTABLISHED) {
 		kfree_skb(skb);
 		ret = NET_XMIT_DROP;
 		goto out_unlock;
 	}

 	/* Report transmitted length before we add encap header, which keeps
 	 * statistics consistent for both UDP and IP encap tx/rx paths.
 	 */
 	*len = skb->len;

 	inet = inet_sk(sk);
 	switch (tunnel->encap) {
 	case L2TP_ENCAPTYPE_UDP:
 		/* Setup UDP header */
 		__skb_push(skb, sizeof(*uh));
 		skb_reset_transport_header(skb);
 		uh = udp_hdr(skb);
 		uh->source = inet->inet_sport;
 		uh->dest = inet->inet_dport;
 		udp_len = uhlen + session->hdr_len + data_len;
+		if (udp_len > U16_MAX) {
+			kfree_skb(skb);
+			ret = NET_XMIT_DROP;
+			goto out_unlock;
+		}
 		uh->len = htons(udp_len);

 		/* Calculate UDP checksum if configured to do so */
 #if IS_ENABLED(CONFIG_IPV6)
 		if (l2tp_sk_is_v6(sk))
 			udp6_set_csum(udp_get_no_check6_tx(sk),
 				      skb, &inet6_sk(sk)->saddr,
 				      &sk->sk_v6_daddr, udp_len);
 		else
 #endif
 			udp_set_csum(sk->sk_no_check_tx, skb, inet->inet_saddr,
 				     inet->inet_daddr, udp_len);
 		break;

 	case L2TP_ENCAPTYPE_IP:
 		break;
 	}

 	ret = l2tp_xmit_queue(tunnel, skb, &inet->cork.fl);

 out_unlock:
 	spin_unlock(&sk->sk_lock.slock);

 	return ret;
 }



